@extends('layouts.app') @section('title','Staff Schedules') @section('page-title','Staff schedules') @section('content')<div class="schedule-grid">@foreach($staffMembers as $s)<section class="panel"><div class="panel-head"><div><h2>{{ $s->full_name }}</h2><p>{{ $s->specialty }}</p></div></div>@php($days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'])@foreach(range(0,6) as $d)@php($sch=$s->schedules->firstWhere('day_of_week',$d))<form class="schedule-row" method="POST" action="{{ route('staff.schedule.store') }}">@csrf<input type="hidden" name="staff_id" value="{{ $s->id }}"><input type="hidden" name="day_of_week" value="{{ $d }}"><b>{{ $days[$d] }}</b><input type="time" name="start_time" value="{{ $sch?substr($sch->start_time,0,5):'10:00' }}"><span>to</span><input type="time" name="end_time" value="{{ $sch?substr($sch->end_time,0,5):'20:00' }}"><button class="btn btn-small">{{ $sch?'Update':'Add' }}</button>@if($sch)<button class="link-danger" form="delete-sch-{{ $sch->id }}" type="submit">×</button>@endif</form>@if($sch)<form id="delete-sch-{{ $sch->id }}" method="POST" action="{{ route('staff.schedule.destroy',$sch) }}">@csrf @method('DELETE')</form>@endif @endforeach</section>@endforeach</div>@endsection
